    HazardsController_create: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["CreateHazardDto"];
            };
        };
        responses: {
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["HazardResponseDto"];
                };
            };
            /** @description Two distinct shapes: (a) the `hazard_reporting` operator kill switch is `force_off` — the forbidden envelope (`Feature unavailable: hazard_reporting`) carrying `feature: "hazard_reporting"` but no `code`/`limit`/`current`; or (b) the caller is at their `hazard_reports_per_day` cap (anti-abuse rate limit, same for all tiers; an operator can set it to 0 as a reporting kill switch) — `FeatureLimitExceededDto` carrying `code: "FEATURE_LIMIT_EXCEEDED"`, `feature: "hazard_reports_per_day"`, `limit`, and `current`. Discriminate on the presence of `code` (both shapes carry `feature`). */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["FeatureForbiddenDto"] | components["schemas"]["FeatureLimitExceededDto"];
                };
            };
            /** @description The submitted `photo_url` refers to a managed upload the orphan sweep already reclaimed (the report was queued past the 24h grace window) — `HazardPhotoExpiredDto` carrying `code: "HAZARD_PHOTO_EXPIRED"`. The client must re-upload from its retained local photo and resubmit. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["HazardPhotoExpiredDto"];
                };
            };
        };
    };
    HazardsController_uploadPhoto: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "multipart/form-data": {
                    /** Format: binary */
                    file: string;
                };
            };
        };
        responses: {
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["HazardPhotoUploadResponseDto"];
                };
            };
            /** @description Invalid file type or empty body */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The `hazard_reporting` operator kill switch is `force_off` — the photo upload is blocked (not just `POST /hazards`) so a shutdown also stops the multipart buffering + image write during an abuse incident. The forbidden envelope carries `feature: "hazard_reporting"`. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["FeatureForbiddenDto"];
                };
            };
            /** @description Too many photos awaiting a report — the caller is at the per-user pending-upload quota. Attach or discard existing uploads first. */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
